import random
import statistics


def info_bernoulli(p, n):
    """Fisher information about p in n independent trades."""
    return n / (p * (1 - p))


def observed_info(loglik, theta, h):
    """Minus the central second difference of loglik at theta, step h."""
    return -(loglik(theta + h) - 2 * loglik(theta) + loglik(theta - h)) / h ** 2


def mle_sd(p, n, reps, seed):
    """Spread of k/n over reps simulated samples of n trades."""
    rng = random.Random(seed)
    ests = []
    for _ in range(reps):
        k = sum(1 for _ in range(n) if rng.random() < p)
        ests.append(k / n)
    return statistics.pstdev(ests)
